let flags = [];

// Convert inputs to lowercase strings to handle variations like "True", "TRUE", "yes" safely
let status = String($blacklist_status).toLowerCase();
let risk = String($risk_rating).toLowerCase();

// Check Blacklist Status
if (status === "true" || status === "yes" || status === "blacklisted" || status === "1") {
    flags.push(`CRITICAL: Vendor ${$vendor_name} is actively BLACKLISTED in the system.`);
}

// Check Risk Rating
if (risk === "high") {
    flags.push(`WARNING: Vendor ${$vendor_name} currently holds a HIGH risk rating.`);
}

// Final Evaluation (Must return a string)
if (flags.length > 0) {
    return flags.join(" | ");
} else {
    return `PASS: Vendor ${$vendor_name} is not blacklisted and their risk rating is acceptable.`;
}
